def find_minimal_edit(s_in, s_out):
    """Find the smallest change needed to transform s_in to s_out"""
    # Simple approach: find first differing character position
    min_len = min(len(s_in), len(s_out))

    # Check for insertion/deletion at beginning
    if s_in[:min_len] == s_out[:min_len]:
        if len(s_in) < len(s_out):
            return (s_in[min_len:], s_out[min_len:], min_len)
        else:
            return (s_in[min_len:], s_out[min_len:], min_len)

    # Find first difference
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if it's a substitution
            old_sub = s_in[i:i+1]
            new_sub = s_out[i:i+1]
            return (old_sub, new_sub, i)

    # If we reach here, one string is prefix of the other
    if len(s_in) < len(s_out):
        return (s_in[min_len:], s_out[min_len:], min_len)
    else:
        return (s_in[min_len:], s_out[min_len:], min_len)

